/// failures fail again — else passes (a pure ws drop heals).
String stubRunner(String tmp) =>
    '''
#!/usr/bin/env bash
main=''
for a in "\$@"; do
  case "\$a" in --file-reporter=json:*) main="\${a#--file-reporter=json:}" ;; esac
